  var segarkanSertifikat = function () { };

  function skalakanSertifikat() {
    var lbr = document.getElementById("lembar-sertifikat");
    if (!lbr) return;
    var wadah = lbr.parentNode;
    var lebar = wadah.clientWidth || 1;
    var skala = Math.min(1, lebar / 1600);
    lbr.style.transform = "scale(" + skala + ")";
    wadah.style.height = Math.ceil(1131 * skala) + "px";
  }
  window.addEventListener("resize", skalakanSertifikat);

  /* ---------- menyejajarkan sampul dengan lembar modul ---------- */
  function selaraskanSampul() {
    /* Sampul memenuhi seluruh layar melalui tata letak kisi. Yang perlu diatur hanya
       ruang bawah panel, agar bilah alat pada ponsel tidak menutupi tombol. */
    var sampulEl = document.getElementById("sampul");
    if (!sampulEl) return;
    var panel = sampulEl.querySelector(".hero");
    if (!panel) return;
    var bilahEl = document.querySelector(".bilah");
    var lebarL = document.documentElement.clientWidth;
    var penuh = lebarL <= 620;
    var angkat = (penuh && bilahEl) ? Math.round(bilahEl.getBoundingClientRect().height) + 14 : 0;
    panel.style.paddingBottom = angkat ? angkat + "px" : "";
  }
  if (document.fonts && document.fonts.ready && document.fonts.ready.then) {
    document.fonts.ready.then(function () { selaraskanSampul(); });
  }
  window.addEventListener("resize", selaraskanSampul);
  window.addEventListener("beforeprint", function () {
    Array.prototype.forEach.call(document.querySelectorAll(".batas, .unit-kepala, h3.bagian"),
      function (el) { el.classList.add("tampil"); });
  });

  var REGISTER = [];   // untuk mengunduh jawaban

  /* ---------- penyimpanan suntingan teks ---------- */
  var KUNCI_SUNTING = KUNCI_SIMPAN + "-sunting";
  var SUNTINGAN = {};
  try {
    var bawaan = window.__SUNTINGAN_AWAL || {};
    for (var kb in bawaan) { if (Object.prototype.hasOwnProperty.call(bawaan, kb)) SUNTINGAN[kb] = bawaan[kb]; }
    var simpanan = JSON.parse(window.localStorage.getItem(KUNCI_SUNTING) || "null") || {};
    for (var ks in simpanan) { if (Object.prototype.hasOwnProperty.call(simpanan, ks)) SUNTINGAN[ks] = simpanan[ks]; }
  } catch (e) { SUNTINGAN = window.__SUNTINGAN_AWAL || {}; }
